package com.videokit.spike.c14;
import android.content.Context;
import android.os.Bundle;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import org.junit.*;
import org.junit.runner.RunWith;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class)
public final class C14EncoderDeviceTests {
    private Context context(){return InstrumentationRegistry.getInstrumentation().getTargetContext();}
    private Path directory(){return new File(context().getCacheDir(),"d1_c14_pipeline_outputs").toPath();}
    private AsyncReadBridge.Provider source()throws IOException{return HostFixtures.file(new File(DeviceFixtures.directory(context()),"basic.mp4").toPath());}
    @Before public void environment(){CpuEnvironment.Snapshot state=CpuEnvironment.inspect(context());Bundle status=new Bundle();status.putString("stream",(state.ready()?"C14_ENVIRONMENT_READY ":"C14_ENVIRONMENT_BLOCKED ")+state.details()+"\n");InstrumentationRegistry.getInstrumentation().sendStatus(0,status);Assume.assumeTrue("ENVIRONMENT_BLOCKED",state.ready());}
    private void supported(RealFramePipeline.Report r){if(r.status.equals("CAPABILITY_BLOCKED")){Bundle status=new Bundle();status.putString("stream","C14_PIPELINE_CAPABILITY_BLOCKED "+r.error+"\n");InstrumentationRegistry.getInstrumentation().sendStatus(0,status);Assume.assumeTrue("CAPABILITY_BLOCKED",false);}}
    private void released(RealFramePipeline.Report r){assertTrue(r.resourcesReleased);assertTrue(r.sourceReleased);assertTrue(r.codecReleased);assertTrue(r.writerReleased);assertTrue(r.framesReleased);assertEquals(0,r.encoderPending);assertFalse(r.encoderCreating);assertFalse(r.encoderHeldImage);assertFalse(r.encoderHeldCodec);assertFalse(r.encoderRgbaHeld);assertFalse(r.encoderYuvHeld);assertEquals(0,r.queued);assertEquals(0,r.offers);assertEquals(0,r.retainedCpuTasks);assertEquals(0,RealFramePipeline.reservedEncoderOutputSlots());assertTrue(RealFramePipeline.quarantinedIds().isEmpty());}
    @Test public void encoderPublicCapabilitySnapshot()throws Exception{List<EncoderNegotiation.Candidate> plan=new EncoderCapabilities().enumerate(phase->{});assertTrue(plan.size()<=4);Set<String> keys=new HashSet<>();for(EncoderNegotiation.Candidate c:plan){assertTrue(keys.add(c.key()));assertTrue(c.color==19 || c.color==21 || c.color==EncoderNegotiation.FLEX);}assertEquals(0,RealFramePipeline.reservedEncoderOutputSlots());}
    @Test public void encoderCapabilityDenialCreatesNothing()throws Exception{try(RealFramePipeline p=new RealFramePipeline(context(),source(),CpuTaskClient.MP4_H264,directory(),"capability-deny")){RealFramePipeline.Report r=p.await(20000);released(r);assertEquals("CAPABILITY_BLOCKED",r.status);assertEquals(0,r.encoderAttempts);assertEquals(0,r.received);assertEquals(0,r.inputs);assertEquals(0,r.bytes);assertNull(r.firstAttemptError);assertNull(r.token);}}
    @Test public void encoderRejectedConfigurationReleasesBeforeNext()throws Exception{try(RealFramePipeline p=new RealFramePipeline(context(),source(),CpuTaskClient.MP4_H264,directory(),"configure-first")){RealFramePipeline.Report r=p.await(90000);supported(r);released(r);assertEquals("READY",r.status);assertNull(r.error);assertEquals("PIPE_ENCODER_CONFIGURE_FAILED",r.firstAttemptError);assertTrue(r.encoderAttempts>=2 && r.encoderAttempts<=4);assertEquals(6,r.received);assertEquals(6,r.inputs);assertEquals(6,r.outputs);assertEquals(6,r.verified);assertNotNull(r.token);}}
    @Test public void encoderAllRejectedNoSourceWriter()throws Exception{try(RealFramePipeline p=new RealFramePipeline(context(),source(),CpuTaskClient.MP4_H264,directory(),"configure-all")){RealFramePipeline.Report r=p.await(25000);supported(r);released(r);assertEquals("ABORTED",r.status);assertEquals("PIPE_ENCODER_CONFIGURE_FAILED",r.error);assertTrue(r.encoderAttempts>=1 && r.encoderAttempts<=4);assertFalse(r.encoderSelected);assertEquals(0,r.received);assertEquals(0,r.inputs);assertEquals(0,r.bytes);assertNull(r.token);}}
    @Test public void encoderCancelDuringNegotiationRetainsPermit()throws Exception{try(RealFramePipeline p=new RealFramePipeline(context(),source(),CpuTaskClient.MP4_H264,directory(),"configure-cancel-gate")){int heldAttempts;try{if(!p.negotiationEntered.await(15,TimeUnit.SECONDS)){RealFramePipeline.Report early=p.await(1000);supported(early);fail("actual configure gate not reached");}InstrumentationRegistry.getInstrumentation().runOnMainSync(p::cancel);RealFramePipeline.Report held=p.query();heldAttempts=held.encoderAttempts;assertTrue(heldAttempts>=1 && heldAttempts<=4);assertEquals("PENDING",held.status);assertEquals(1,held.encoderPending);assertFalse(held.resourcesReleased);assertEquals(1,RealFramePipeline.reservedEncoderOutputSlots());assertEquals(0,held.received);assertEquals(0,held.bytes);}finally{p.negotiationRelease.countDown();}RealFramePipeline.Report r=p.await(15000);released(r);assertEquals("ABORTED",r.status);assertEquals("PIPE_CANCELLED",r.error);assertEquals(heldAttempts,r.encoderAttempts);assertEquals(0,r.inputs);}}
    @Test public void encoderCloseAckUnprovenStopsSelection()throws Exception{try(RealFramePipeline p=new RealFramePipeline(context(),source(),CpuTaskClient.MP4_H264,directory(),"configure-close-ack-loss")){RealFramePipeline.Report held=p.await(25000);supported(held);assertEquals("PENDING",held.status);assertEquals(1,held.encoderAttempts);assertEquals(0,held.encoderPending);assertFalse(held.codecReleased);assertFalse(held.resourcesReleased);assertEquals(0,held.received);assertEquals(0,held.bytes);assertEquals(1,RealFramePipeline.reservedEncoderOutputSlots());assertNull(held.token);p.confirmActualReleaseForTest();RealFramePipeline.Report r=p.recover(5000);released(r);assertEquals("ABORTED",r.status);assertEquals(1,r.encoderAttempts);assertEquals("PIPE_ENCODER_CONFIGURE_FAILED",r.firstAttemptError);}}
}
